#include "test.hpp"
#include "mspa/mspa.hpp"
using namespace mspa;
static PsychologicalProfile make_profile(std::uint64_t id,float sociability,float curiosity,float boldness){PsychologicalProfile p{};p.id=ProfileId(id);p.name="profile_"+std::to_string(id);p.personality={sociability,0.6f,0.6f,0.6f,curiosity,boldness};p.values.push_back({ConceptId(1000+id),0.6f});p.goals.push_back({ConceptId(2000+id),0.7f,0.8f});return p;}
int main(){
    ProfileRegistry registry;require(registry.size()==0,"profile registry starts empty; core owns no consumer presets");
    require(registry.add(make_profile(1,0.45f,0.35f,0.30f)),"register first host profile");require(registry.add(make_profile(2,0.75f,0.70f,0.60f)),"register second host profile");require(registry.add(make_profile(3,0.60f,0.85f,0.80f)),"register third host profile");require(registry.size()==3,"host can register its current three profiles");
    for(std::uint64_t i=4;i<=13;++i)require(registry.add(make_profile(i,0.5f,0.5f,0.5f)),"registry accepts additional profiles");require(registry.size()==13,"registry is not capped at three");
    ProfileRecipe mix{};mix.components={{ProfileId(1),1.0f},{ProfileId(3),3.0f}};auto resolved=registry.resolve(mix,{WorldId(1),1});require(resolved,"blend registered profiles");require(resolved.value_if()->personality.curiosity>0.35f&&resolved.value_if()->personality.curiosity<0.85f,"weighted profile blend");require(resolved.value_if()->values.size()==2,"profile values are composed");require(resolved.value_if()->goals.size()==2,"profile goals are composed");
    ProfileRecipe varied=mix;varied.variation_seed=77;varied.variation_strength=0.1f;auto a=registry.resolve(varied,{WorldId(1),42});auto b=registry.resolve(varied,{WorldId(1),42});auto c=registry.resolve(varied,{WorldId(1),43});require(a&&b&&c,"deterministic profile variation");require(a.value_if()->personality.sociability==b.value_if()->personality.sociability,"same agent and seed reproduce variation");require(a.value_if()->personality.sociability!=c.value_if()->personality.sociability||a.value_if()->personality.curiosity!=c.value_if()->personality.curiosity,"different agents may vary");
    RuntimeConfig cfg{};cfg.runtime_id=RuntimeId(1);cfg.world_id=WorldId(1);cfg.time_domain={TimeDomainId(1),{1,1}};cfg.seed_root=5;auto rr=Runtime::create(cfg);require(rr,"runtime");auto runtime=std::move(*rr.value_if());AgentId id{WorldId(1),55};ProfileRecipe direct{};direct.components={{ProfileId(2),1.0f}};require(create_agent_from_profiles(*runtime,id,registry,direct,PsychTime(10)),"create agent from registered profile");const auto*state=runtime->agents().find(id);require(state!=nullptr,"profiled agent exists");require(state->personality.sociability==registry.find(ProfileId(2))->personality.sociability,"profile personality applied");require(!state->values.empty()&&!state->goals.empty(),"profile seeds values and goals");
    auto init=materialize_profile_init(registry,mix,{WorldId(1),56},PsychTime(20));require(init,"materialize profile independently");init.value_if()->personality.empathy=1.0f;require(runtime->create_agent({WorldId(1),56},*init.value_if(),PsychTime(20)),"materialized init remains customizable");
    require(registry.remove(ProfileId(13)),"remove profile");require(!registry.contains(ProfileId(13)),"removed profile unavailable");
    std::cout<<"profiles ok\n";
}
